compact/posix/codex/voyageai/claude-code.copy:
# Keep generated configuration files out of version control.
echo .chunkhound.json >> .gitignore
# Configure ChunkHound with VoyageAI embeddings and Claude Code CLI for research. Embedding and LLM providers are independent — either works without the other. Field details: https://chunkhound.ai/docs/configuration/
# You'll need: VoyageAI API key
cat > .chunkhound.json <<'CHUNKHOUND_EOF'
{
  "embedding": {
    "provider": "voyageai",
    "model": "voyage-4-lite",
    "api_key": "<YOUR_VOYAGE_API_KEY>"
  },
  "llm": {
    "provider": "claude-code-cli"
  }
}
CHUNKHOUND_EOF
# Configure Codex to connect to ChunkHound via MCP.
codex mcp add ChunkHound -- chunkhound mcp
# Build ChunkHound's search index for this project.
chunkhound index .
